var hud=UnityEngine.Object.FindFirstObjectByType<Corrigible.Fx.FxRaidHud>();var game=UnityEngine.Object.FindFirstObjectByType<Corrigible.Game.GameController>();var checks=new System.Collections.Generic.List<object>();int failed=0;void Check(string name,bool ok,object detail=null){checks.Add(new{name,ok,detail});if(!ok)failed++;}
string folder="Docs/UI_Fx/captures/Live";
try{
Check("canlı-eklemeli-baskın",hud!=null&&hud.source is Corrigible.Fx.FxLiveRaidSource&&UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="FxBaskin");Check("tek-event-system",UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(UnityEngine.FindObjectsSortMode.None).Count(x=>x.isActiveAndEnabled)==1);Check("tek-fx-saat",UnityEngine.Object.FindObjectsByType<Corrigible.Fx.FxClock>(UnityEngine.FindObjectsSortMode.None).Count(x=>x.enabled)==1);
var expected=Corrigible.Core.Baskin.Create(game.Sim.S.Raid.Params);Check("gerçek-baskın-parametreleri",Newtonsoft.Json.JsonConvert.SerializeObject(expected)==Newtonsoft.Json.JsonConvert.SerializeObject(hud.source.State));
var before=Newtonsoft.Json.JsonConvert.SerializeObject(hud.source.State);hud.LoadScreen(9);hud.LoadBoard("B7b");Check("canlı-örnek-yüklenemez",before==Newtonsoft.Json.JsonConvert.SerializeObject(hud.source.State));
Corrigible.Fx.EditorTools.FxCaptureTools.Capture(folder+"/raid-tr.png");Corrigible.Desk.DeskLoc.Instance.SetLanguage(Corrigible.Desk.DeskLang.En);Corrigible.Fx.EditorTools.FxCaptureTools.Capture(folder+"/raid-en.png");Corrigible.Desk.DeskLoc.Instance.SetLanguage(Corrigible.Desk.DeskLang.Tr);
hud.SelectUnit(Convert.ToChar("T"));var start=hud.source.State.Clone();hud.MoveSelectedTo(hud.Model.Moves.First());Check("canlı-hamle",hud.Model.CanUndo);hud.Undo();Check("canlı-geri-al",Newtonsoft.Json.JsonConvert.SerializeObject(start)==Newtonsoft.Json.JsonConvert.SerializeObject(hud.source.State));
var canonical=hud.source.State.Clone();Corrigible.Core.Baskin.EndTurn(canonical);hud.EndTurn();if(!hud.source.MachineRunning)hud.EndTurn();Check("makineler-girdi-kilidi",hud.source.MachineRunning&&hud.Model.Locked&&hud.BoardBlocked);hud.EndTurn();for(int n=0;n<300&&hud.source.MachineRunning;n++)hud.source.TickMachines(hud.clock.Now+n+1);Check("makineler-tek-çözüm",Newtonsoft.Json.JsonConvert.SerializeObject(canonical)==Newtonsoft.Json.JsonConvert.SerializeObject(hud.source.State));
hud.RequestRetreat();Check("geri-çekilme-onay",hud.Model.RetreatArmed&&!hud.Model.Finished);hud.RequestRetreat();Check("geri-çekilme-sonuç",hud.Model.Finished&&!hud.Model.Success);Corrigible.Fx.EditorTools.FxCaptureTools.Capture(folder+"/raid-retreat.png");hud.ContinueToReport();hud.ContinueToReport();Check("sonuç-tek-kayıt",((Corrigible.Fx.FxLiveRaidSource)hud.source).ResultReported&&game.Sim.Record.commands.Count(c=>c.kind=="raidres")==1&&game.Sim.S.Raid==null);
}catch(System.Exception e){Check("exception",false,e.ToString());}
var result=new{total=checks.Count,failed,checks};System.IO.File.WriteAllText(folder+"/raid-qa.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{total=checks.Count,failed};
